sealed class ConstellationMap : Grid {
 readonly Canvas canvas;readonly ScrollViewer scroll;readonly StarField field;readonly List<Button> nodes=new List<Button>();
 readonly TextBlock caption;ChallengeProgress state;int selected;public bool SelectionLocked{get;set;}public event Action<int> Requested;
 const double Step=122,Inset=62;
 static readonly Style NodeStyle=(Style)XamlReader.Parse(@"<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Button'><Setter Property='Foreground' Value='#A7B8CF'/><Setter Property='Background' Value='#131F32'/><Setter Property='BorderBrush' Value='#3A5272'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='Button'><Grid><Ellipse x:Name='halo' Fill='Transparent' Stroke='{TemplateBinding BorderBrush}' StrokeThickness='1' Opacity='.35' Margin='-5'/><Ellipse x:Name='disc' Fill='{TemplateBinding Background}' Stroke='{TemplateBinding BorderBrush}' StrokeThickness='1.5'/><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center'/></Grid><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='halo' Property='Opacity' Value='1'/><Setter TargetName='disc' Property='Fill' Value='#294363'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='halo' Property='Stroke' Value='#D5E9FF'/><Setter TargetName='halo' Property='Opacity' Value='1'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='disc' Property='Fill' Value='#365C86'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
 public ConstellationMap(){RowDefinitions.Add(new RowDefinition{Height=new GridLength(26)});RowDefinitions.Add(new RowDefinition{Height=new GridLength(112)});Background=Dark.Bg;var top=new DockPanel{Margin=new Thickness(15,0,10,0)};var arrows=new StackPanel{Orientation=Orientation.Horizontal};var left=Dark.Button("‹");var right=Dark.Button("›");left.MinHeight=right.MinHeight=22;left.Padding=right.Padding=new Thickness(12,0,12,0);left.ToolTip="向前查看星轨";right.ToolTip="向后查看星轨";left.Click+=(s,e)=>scroll.ScrollToHorizontalOffset(Math.Max(0,scroll.HorizontalOffset-scroll.ViewportWidth*.75));right.Click+=(s,e)=>scroll.ScrollToHorizontalOffset(scroll.HorizontalOffset+scroll.ViewportWidth*.75);arrows.Children.Add(left);arrows.Children.Add(right);DockPanel.SetDock(arrows,Dock.Right);top.Children.Add(arrows);caption=Dark.Text("CONSTELLATION  /  50 颗星 · 向右探索",10,true,Dark.Accent);top.Children.Add(caption);Children.Add(top);
  canvas=new Canvas{Width=Inset*2+Step*49,Height=100,Background=Dark.Bg};field=new StarField{Width=canvas.Width,Height=100,IsHitTestVisible=false};canvas.Children.Add(field);scroll=new ScrollViewer{Content=canvas,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,Background=Dark.Bg,CanContentScroll=false,PanningMode=PanningMode.HorizontalOnly};scroll.PreviewMouseWheel+=(s,e)=>{scroll.ScrollToHorizontalOffset(scroll.HorizontalOffset-e.Delta*2);e.Handled=true;};scroll.Resources[typeof(System.Windows.Controls.Primitives.ScrollBar)]=Dark.ScrollStyle;Grid.SetRow(scroll,1);Children.Add(scroll);
  for(int i=0;i<50;i++){int n=i+1;var button=new Button{Style=NodeStyle,Width=30,Height=30,FontSize=10,FontFamily=new FontFamily("Consolas"),Cursor=Cursors.Hand,Content=n.ToString("00"),Tag=n};System.Windows.Automation.AutomationProperties.SetName(button,"第"+n+"关 · "+ChallengeBank.Levels[i].Problem.Title);Canvas.SetLeft(button,X(i)-15);Canvas.SetTop(button,Y(i)-15);button.Click+=(s,e)=>{var h=Requested;if(h!=null)h(n);};button.PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Left||e.Key==Key.Right){int target=Math.Max(1,Math.Min(50,selected+(e.Key==Key.Right?1:-1)));var h=Requested;if(h!=null)h(target);e.Handled=true;}};canvas.Children.Add(button);nodes.Add(button);
   string title=ChallengeBank.Levels[i].Problem.Title;int split=title.IndexOf('·');if(split>0)title=title.Substring(0,split).Trim();var label=Dark.Text(title,10,false,Dark.Muted);label.Width=114;label.TextAlignment=TextAlignment.Center;label.TextTrimming=TextTrimming.CharacterEllipsis;label.TextWrapping=TextWrapping.NoWrap;label.IsHitTestVisible=false;Canvas.SetLeft(label,X(i)-57);Canvas.SetTop(label,Y(i)+21);canvas.Children.Add(label);
  }Loaded+=(s,e)=>FocusSelected(false);
 }
 public static double X(int i){return Inset+i*Step;}
 public static double Y(int i){double[] wave={40,27,38,57,47,27,40,57,40,27};return wave[i%10];}
 public void Refresh(ChallengeProgress progress){state=progress;for(int i=0;i<50;i++){var node=nodes[i];bool passed=state.Passed(i+1),unlocked=i+1<=state.Unlocked;node.Foreground=passed?Theme.B("#95E6D5"):unlocked?Dark.Ink:Theme.B("#7F8DA3");node.BorderBrush=passed?Theme.B("#5EAFA5"):unlocked?Dark.Accent:Theme.B("#35445D");node.Background=passed?Theme.B("#13323A"):Theme.B("#111C2E");node.ToolTip=(passed?"已通关 · ":unlocked?"可挑战 · ":"未解锁 · ")+ChallengeBank.Levels[i].Problem.Title+"\n限时"+ChallengeBank.Levels[i].Seconds/60+"分钟 · 第"+(i/10+1)+"章 "+ChallengeBank.Chapters[i/10];}field.Progress=progress;field.InvalidateVisual();if(selected>0)SetSelected(selected,false);}
 public void SetSelected(int n,bool animate=true){selected=n;caption.Text="第 "+((n-1)/10+1)+" 章 · "+ChallengeBank.Chapters[(n-1)/10]+"    /    "+n.ToString("00")+" · 50 颗星";for(int i=0;i<50;i++){nodes[i].BorderThickness=new Thickness(i==n-1?2:1);bool passed=state!=null&&state.Passed(i+1),unlocked=state!=null&&i+1<=state.Unlocked;nodes[i].Background=passed?Theme.B("#13323A"):Theme.B("#111C2E");nodes[i].BorderBrush=passed?Theme.B("#5EAFA5"):unlocked?Dark.Accent:Theme.B("#35445D");nodes[i].Foreground=passed?Theme.B("#95E6D5"):unlocked?Dark.Ink:Theme.B("#7F8DA3");if(i==n-1){nodes[i].Background=Theme.B("#245078");nodes[i].BorderBrush=Theme.B("#BBDEFF");nodes[i].Foreground=Brushes.White;}}field.Selected=n;field.InvalidateVisual();FocusSelected(animate);}
 void FocusSelected(bool animate){if(selected<1||scroll.ViewportWidth<=0)return;double x=X(selected-1),left=scroll.HorizontalOffset,right=left+scroll.ViewportWidth;if(x<left+50||x>right-50)scroll.ScrollToHorizontalOffset(Math.Max(0,x-scroll.ViewportWidth*.4));if(animate){var node=nodes[selected-1];node.BeginAnimation(OpacityProperty,new DoubleAnimation(.45,1,TimeSpan.FromMilliseconds(320)));}}
 public int SelectedNumber{get{return selected;}}public ScrollViewer Scroller{get{return scroll;}}
 sealed class StarField : FrameworkElement {
  public ChallengeProgress Progress;public int Selected;
  protected override void OnRender(DrawingContext dc){base.OnRender(dc);var random=new Random(121);for(int i=0;i<470;i++){double x=random.NextDouble()*ActualWidth,y=random.NextDouble()*95;dc.DrawEllipse(Theme.B(i%5==0?"#486B96":"#243A57"),null,new Point(x,y),i%5==0?1.1:.55,i%5==0?1.1:.55);}for(int i=0;i<49;i++){var a=new Point(X(i),Y(i));var b=new Point(X(i+1),Y(i+1));bool reached=Progress!=null&&Progress.Passed(i+1);dc.DrawLine(new Pen(Theme.B(reached?"#24547A":"#14253B"),5),a,b);var pen=new Pen(Theme.B(reached?"#75C4DE":"#36506C"),1);if(!reached)pen.DashStyle=new DashStyle(new double[]{3,4},0);dc.DrawLine(pen,a,b);if((i+1)%10==0)dc.DrawLine(new Pen(Theme.B("#233A55"),1),new Point((a.X+b.X)/2,5),new Point((a.X+b.X)/2,90));}if(Selected>0){var p=new Point(X(Selected-1),Y(Selected-1));dc.DrawEllipse(new RadialGradientBrush(Color.FromArgb(95,105,183,255),Colors.Transparent),null,p,31,31);dc.DrawEllipse(null,new Pen(Theme.B("#395C82"),1),p,21,21);}}
 }
}
